Definition isl_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition isl_pure (sp : word) (P IN E lo : Z) (c : pcore) (p0 : Z) (bs : list byte) : Prop :=
  pcore_ok c /\ lo + 192 <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= p0) /\ p0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= P /\ P + 256 <= 2^64 /\ bv_unsigned sp <= IN /\ IN + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (P + 256 <= IN \/ IN + 8 <= P) /\ (P + 256 <= E \/ E + 24 <= P) /\ (IN + 8 <= E \/ E + 24 <= IN).

(* [comment removed for export] *)
Definition isl_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' e loc,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (isl_W lo sp P E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells usegs m' IN [C8 (wz p0)]
    /\ rw_cells usegs m' E (ErrCodeCells (EC_http_loc e loc))
    /\ In e [HE_NEED_MORE; HE_BAD_METHOD; HE_BAD_TARGET; HE_BAD_VERSION] /\ Z.even loc = true /\ 4 <= loc /\ loc + 1 < 2^64
    /\ bytes_at usegs m' p0 bs
    /\ HttpCat m' true /\ XStatics m'.

Definition isl_sv (s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word := [s7; s6; s5; s4; s3; s2; s1; s0; ra].

(* [comment removed for export] *)
Definition isl_ctx (m m1 : mem) (sp : word) (sv : list word) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte)
    (p0 : Z) (bs : list byte) (Ec : ecv) (g : bool) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -72) (map C8 sv)
  /\ rw_cells usegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells usegs m1 IN [C8 (wz p0)]
  /\ rw_cells usegs m1 E (ErrCodeCells Ec)
  /\ bytes_at usegs m1 p0 bs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -112)
  /\ munch (isl_W lo sp P E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Local Ltac isl_finish e loc :=
  apply evt_done; unfold isl_ret_post;
  do 16 eexists; exists e, loc;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition isl_exit_stmt (pc e loc : Z) : Prop :=
  forall (lowc : list cell) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 last : Z) (bs : list byte)
    (junk : list byte) (Ec : ecv) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs Ec g ->
  rw_cells usegs m1 (bv_unsigned sp + -112) lowc -> cells_size lowc = 16%nat ->
  rw_cells usegs m1 (bv_unsigned sp + -96) [CB 24 junk] ->
  isl_pure sp P IN E lo c p0 bs ->
  evt usegs (isl_ret_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              (wz IN) (wz last) s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

Local Ltac isl_exit_script e loc pcstore :=
  intros lowc rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4x s5x s6x s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P IN E lo c pad7 pad2 p0 last bs junk Ec g;
  intros CTX LOW SL TMP PURE;
  destruct CTX as (FRhi & PC & IT & EC & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & LO & IMG & QLO & QHI & PLO & PHI & ILO & IHI & ELO & EHI & DPI & DPE & DIE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold isl_W, G_HTTP_CAT in *; unfold isl_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold ErrCodeCells in EC;
  destruct (rw_cells_forget _ _ _ _ LOW) as [jl LOWb]; rewrite SL in LOWb; clear LOW;
  unfold wz in *;
  (* [comment removed for export] *)
  steps_to 0x34360%Z;
  call_assignA_with (bv_unsigned sp + -112) (bv_unsigned sp + -96) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP' : rw_cells _ ?mx (bv_unsigned sp + -96) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP';
    steps_to pcstore;
    expose_statics HC XS [(E, E + 24)]%Z;
    st1; st1; st1;
    steps_to 0x3e814%Z;
    (* [comment removed for export] *)
    do 9 step;
    destruct (rw_cells_forget _ _ _ _ TMP') as [junk' TMPb]; cbn [cells_size csize Nat.add] in TMPb; clear TMP';
    pose proof (rw_cells_CB_join usegs _ _ _ _ _ _ LOWb ltac:(lazymatch type of TMPb with rw_cells _ _ ?a _ =>
        replace a with (bv_unsigned sp + -112 + Z.of_nat 16) in TMPb by lia end; exact TMPb)) as J1;
    clear LOWb TMPb; change (16 + 24)%nat with 40%nat in J1;
    join_frame J1 FRhi (bv_unsigned sp + -112);
    lazymatch goal with ST'' : stk _ _ lo _ |- _ => step; release_frame J1 ST'' (bv_unsigned sp); step end;
    isl_finish e loc;
    first [ unfold EC_http_loc, ec_make_loc, ErrCodeCells; cbn [ec_val ec_cat ec_flags];
            replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; lia); unfold wz; fast_assumption
          | cbn; qtauto
          | close_HttpCat_chunks
          | lazymatch goal with MU2 : munch [(E, E + 24)]%Z ?my _, WM2 : wmono _ ?my _ |- _ => close_XStatics XS MU2 WM2 end ]
  end.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
